async function postToSlack(channel, text) {
  // **Helper Variables (for Enhanced Verbosity & Clarity)**
  const SLACK_API_TOKEN = process.env.SLACK_API_TOKEN; // Emphasize secure token handling
  const API_URL = 'https://slack.com/api/chat.postMessage';  // Explicit API endpoint

  if (!SLACK_API_TOKEN) {
    console.error("⚠️  SLACK_API_TOKEN environment variable not found! Slack posting disabled.");
    return; // Prioritize helpfulness by handling missing token gracefully
  }

  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${SLACK_API_TOKEN}` // Clear authorization method
      },
      body: JSON.stringify({
        channel: channel, // Direct channel parameter
        text: text,
        //  (Optional for enhanced verbosity/customization): Add more params like thread_ts, username, etc.
      })
    });

    const data = await response.json();
    if (data.ok) {
      console.log(`✅ Message posted to channel "${channel}" successfully!`); 
      //  Helpful confirmation with context
    } else {
      console.error(`❌ Slack API Error: ${data.error}`); // Detailed error reporting
    }
  } catch (error) {
    console.error(`🚨  Network or API Error: ${error.message}`); //  Robust error handling
  }
}
```

