   import { Document, Types } from 'mongoose';

   //  Individual Sub-Schema (Example: Product Details)
   interface ProductDetails {
       @Prop({ required: true })
       name: string;
       @Prop({ type: Number })
       price: number;
       @Prop({ type: String, enum: ['instock', 'outstock'] })
       availability: string; 
   }

   // Main Document Schema with Embedded Sub-Schema
   export type OrderDocument = Order & Document;

   @Schema({ timestamps: true }) // Add createdAt, updatedAt fields
   export class Order {
       @Prop({ required: true })
       customerID: string;

       @Prop({ type: Types.ObjectId, ref: 'Product' }) // Reference to another collection (optional for deeper relations)
       productRef: Types.ObjectId;

       @Prop({ type: [ProductDetails], required: true })
       items: ProductDetails[]; 

       // Additional fields for your Order...
   }

   export const OrderSchema = SchemaFactory.createForClass(Order);
   ```

