// **Vertical Video Stacking & Subtitles Script (After Effects)**

import { app, project, File } from 'aftereffects';
const desktopPath = File(app.path).parent.fsName + '/Desktop/'; // Construct Desktop path

// 1. Input File Management (Prioritize Verbose Explanation)
let filePath = `${desktopPath}your_folder_name/`; // Replace with your actual folder name
let file1 = filePath + "file1.mp4";  // Footage File 1 (Top Layer)
let file2 = filePath + "file2.mp4";  // Footage File 2 (Bottom Layer)
let subtitlesFile = filePath + "subtitles.txt"; // Text file with subtitle content

try {
    let comp = app.project.activeItem; // Assuming active comp is where you'll work
    let source1 = File(file1).open(comp);  // Open footage as comp layers
    let source2 = File(file2).open(comp);

    // 2. Vertical Composition Setup
    let newComp = comp.duplicate();  // Create a copy of the active composition
    newComp.name = "VerticalVideo";  // Rename for clarity
    newComp.width = Math.min(source1.naturalWidth, source2.naturalWidth); // Match narrower width
    newComp.height = source1.naturalHeight * 2; // Double height for stacking

    // 3. Layer Arrangement & Scaling
    let layer1 = newComp.layers.addVideo(source1);
    layer1.transform.position = [0, 0]; // Top-left corner
    layer1.scale = [1, 1]; // Maintain original aspect

    let layer2 = newComp.layers.addVideo(source2);
    layer2.transform.position = [0, source1.naturalHeight]; // Align bottom layer
    layer2.scale = [1, 1]; // Maintain original aspect

    // 4. Subtitle Integration (Detailed Explanation)
    let subtitleText = File(subtitlesFile).readText().split('\n'); // Read subtitles line by line
    let subtitleLayer = newComp.layers.addProperty('Text'); // Add a text layer
    subtitleLayer.textDocument.content = subtitleText.join('\n'); // Populate with subtitle data

