import Foundation
import XLSWriter // Hypothetical Swift Excel library (adapt using real libraries like SwiftXL or OpenXMLSDK)

func generateSkiSnowComparison(sportPreference: String) -> [[String]] {
    let sportData: [(String, [String : String])] = [
        ("Skiing", [
            "speed": "High - Excellent downhill velocity, carving capabilities.",
            "difficulty": "Moderate initial learning, advanced techniques demanding.",
            "style": "Classic, elegant, emphasizes fluidity and control.",
            "learningCurve": "Relatively gentler start, mastering finesse takes time.",
            "terrainVariety": "Wide adaptability, excels on groomed runs, backcountry, and parks.",
            "trickOpportunities": "Limited compared to snowboarding, but mogul skiing and aerial maneuvers exist."
        ]),
        ("Snowboarding", [
            "speed": "Variable, agile carving possible, freeriding emphasis.",
            "difficulty": "Steeper initial learning curve, balance-centric.",
            "style": "Dynamic, expressive, often associated with coolness and individuality.",
            "learningCurve": "Initially challenging, progression rewarding with freestyle focus.",
            "terrainVariety": "Strong in powder, parks, and off-piste, adapts well to diverse slopes.",
            "trickOpportunities": "Highly versatile, extensive freestyle and park tricks readily available."
        ])
    ]

    var comparisonTable: [[String]] = [["Factor", "Skiing", "Snowboarding"]] // Header row

    for (factor, values) in sportData[sportPreference == "skiing" ? 0 : 1][1].enumerated() {
        comparisonTable.append([factor.0, sportData[sportPreference == "skiing" ? 0 : 1][1][factor.0]!, ""]) // Populate with relevant data
    }

    return comparisonTable
}

